D["高股息_公用事业标题"] = "公用事业：科技退潮日的压舱石"
D["高股息_公用事业内容"] = "9月8日" + H(RED, "大秦铁路收平报4.79元、成交4.05亿元，全天振幅仅0.84%，是16只关注标的中波动最小的一只") + "；" + H(CYAN, "PB 0.58倍、股息率TTM 4.65%") + "，类债属性依旧突出。它的收入跟着" + H(CYAN, "核准运价") + "走，几乎不与经济周期同频，成本又高度刚性。同一天" + H(RED, "石油石化涨3.68%领涨申万一级行业，华锦股份、和顺石油、中曼石油涨停") + "，" + H(ORANGE, "油价高企时铁路的替代性需求反而提升，间接受益于地缘溢价") + "。" + H(GREEN, "当1年定存只剩0.95%、10Y国债只有1.677%，公用事业这类可预期的现金回报依然是稀缺品；它的作用不是让你赚快钱，而是让你在市场剧烈轮动时还能睡得着") + "。"

# ===================== 社区热门话题 5 个 =====================
D["社区话题1_来源"] = "综合社区/雪球/东财热帖"
D["社区话题1_标题"] = "指数涨、个股也涨，创业板却跌1.15%，该不该跟着换方向？"
D["社区话题1_热度"] = "9月8日上证指数涨0.20%报3940.55点，深证成指跌0.52%、创业板指跌1.15%、科创50跌1.52%；全市场3417只个股上涨、74只涨停、仅2026只下跌；成交19784亿元放量140亿元；AI算力概念净流出逾81亿元。"
D["社区话题1_角色1"] = "@机构分析师"
D["社区话题1_观点1"] = H(ORANGE, "不是普涨，是切换") + "：" + H(RED, "基础化工净流入71亿、有色65亿、医药40亿") + "，" + H(GREEN, "计算机流出51亿、电子流出35亿") + "。"
D["社区话题1_角色2"] = "@价值投资者"
D["社区话题1_观点2"] = H(ORANGE, "放量却滞涨要警惕") + "：" + H(CYAN, "放量140亿只换来沪指涨7.85点") + "，" + H(GREEN, "说明增量资金有限") + "。"
D["社区话题1_角色3"] = "@谨慎派"
D["社区话题1_观点3"] = H(ORANGE, "切换的尽头是分歧") + "：" + H(GREEN, "龙版传媒7连板炸板、中石科技重挫14%") + "，" + H(GREEN, "高位股先崩") + "。"
D["社区话题1_观点"] = "我的答案偏向" + H(ORANGE, "“不换方向，但换节奏”") + "。先说为什么不换方向：这一天的下跌集中在" + H(CYAN, "大盘成长股") + "——" + H(GREEN, "宁德时代、北方华创、美的集团、天孚通信四只合计吃掉深成指44.48点，占其跌幅逾六成") + "，这不是全市场的问题，是几只权重股的问题。但节奏必须换，理由是" + H(GREEN, "放量140亿元却只换来沪指涨7.85点，这种“放量滞涨”说明卖压和买盘在同等量级上互相消耗") + "。我的做法是三句话：第一，" + H(RED, "底仓不动，红利与公用事业那一块不因为一天的下跌就调整") + "；第二，" + H(CYAN, "机动仓从“追最强”改成“等回踩”，尤其在农业与化肥批量涨停之后，明天的高开大概率是给昨天的人抬轿") + "；第三，" + H(GREEN, "把观察点放在量能上——如果明天成交额跌回1.9万亿以下而指数还在横盘，那这轮切换大概率是存量博弈的尾声") + "。" + H(ORANGE, "真正需要警惕的是“每天换一个方向”本身：当你发现自己在三天里追了三个不同的板块，问题通常不在市场，在仓位") + "。"
D["社区话题标签1"] = "高低切换"
D["社区话题2_来源"] = "综合社区/雪球/东财热帖"
D["社区话题2_标题"] = "LME铜创历史新高，资源股是上车机会还是最后一棒？"
D["社区话题2_热度"] = "9月7日晚LME三个月期铜突破1月高点创历史新高，盘中最高14533美元/吨，近5日涨近3%、年内涨逾17%、过去12个月涨47%；9月8日伦铜续涨1.61%报14728美元/吨，沪铜主力日盘收涨1.29%报110620元/吨、夜盘最高冲至111720元；A股北方铜业涨逾9%、精艺股份涨停。"
D["社区话题2_角色1"] = "@机构分析师"
D["社区话题2_观点1"] = H(ORANGE, "供给约束是硬的") + "：" + H(RED, "铜精矿TC创历史新低") + "，" + H(RED, "矿山铜供应或现2017年来首次年度下滑") + "。"
D["社区话题2_角色2"] = "@价值投资者"
D["社区话题2_观点2"] = H(ORANGE, "但已涨17%") + "：" + H(CYAN, "年内涨幅不小、12个月涨47%") + "，" + H(GREEN, "没有回调就没有安全垫") + "。"
D["社区话题2_角色3"] = "@谨慎派"
D["社区话题2_观点3"] = H(ORANGE, "关税套利会退潮") + "：" + H(GREEN, "纽约对伦敦溢价是政策产物") + "，" + H(GREEN, "政策变了溢价就没了") + "。"
D["社区话题2_观点"] = "这个问题我的处理方式是" + H(ORANGE, "“把铜和油分开看”") + "。铜这一边，我倾向于把它当作中期配置而非短线博弈：理由是" + H(RED, "驱动它创新高的不是需求故事，而是铜精矿TC加工费创出历史新低——冶炼厂在抢矿，这种供给约束需要以年为单位才能弥合") + "，比油价那种靠事件驱动的地缘溢价要硬得多。国信期货也给出判断：" + H(ORANGE, "若下半年矿山无法显著复苏，全球矿山铜供应将出现2017年以来首次年度下滑") + "。但" + H(GREEN, "“逻辑硬”不等于“现在就买”——年内已经涨了17%、过去12个月涨了47%，短期透支的空间不小") + "。我的做法是" + H(CYAN, "不在涨停板上买，等板块回踩10日线再分批，首次仓位不超过计划的三分之一") + "。至于油，我的答案更保守：" + H(GREEN, "布伦特逼近100美元的位置，价格里有太多地缘溢价，而伊朗与阿曼的谈判已临近收官，这类溢价回吐的速度往往比积累快得多") + "。" + H(ORANGE, "一句话总结：铜可以等回调配，油只做小仓位试探，而且必须提前想好退出点") + "。"
D["社区话题标签2"] = "铜价新高"
D["社区话题3_来源"] = "综合社区/雪球/东财热帖"
D["社区话题3_标题"] = "银行大行跌、城商行涨，手里的银行仓要不要跟着换？"
D["社区话题3_热度"] = "9月8日中国银行跌0.78%报6.39元、农业银行跌0.73%报6.76元、招商银行跌0.41%报40.90元、工商银行跌0.38%报7.94元、建设银行跌0.28%报10.68元；宁波银行涨1.55%报34.66元、杭州银行涨0.94%、江苏银行涨0.91%、邮储银行涨0.56%、重庆银行涨0.45%。"
D["社区话题3_角色1"] = "@机构分析师"
