D["社区话题3_角色2"] = "@价值投资者"
D["社区话题3_观点2"] = H(ORANGE, "但注资补的是资本") + "：" + H(RED, "核心一级资本充足率提升") + "，" + H(RED, "分红可持续性增强") + "。"
D["社区话题3_角色3"] = "@谨慎派"
D["社区话题3_观点3"] = H(ORANGE, "城商行波动更大") + "：" + H(GREEN, "江苏银行核心一级仅8.67%") + "，" + H(GREEN, "需自筹资本") + "。"
D["社区话题3_观点"] = "我的答案是" + H(ORANGE, "“不换，但可以加”") + "。先把两件事分清：大行下跌的原因不是基本面变坏，而是" + H(CYAN, "注资带来的股本摊薄——工行不超1000亿、农行不超1600亿的增发会稀释每股净资产与EPS，市场在第一时间把这个影响计入价格") + "；而城商行上涨的原因是" + H(RED, "它们不在名单内、避开了摊薄，同时PB更低（重庆0.68倍、邮储0.62倍）、股息率更高（江苏4.60%、邮储4.03%）") + "。这是两种完全不同的驱动，不构成“大行变差、城商行变好”的结论。我的做法有三条：第一，" + H(RED, "已有的大行底仓不减，因为注资补的是核心一级资本，中期分红的可持续性反而增强了——六大行中期分红比例已从30%提到31%") + "；第二，" + H(CYAN, "要加就加在大行回调的时候，而不是现在去追已经涨了1.5%的城商行") + "；第三，" + H(GREEN, "城商行里真正需要注意的是资本充足率——江苏银行核心一级仅8.67%、注资又不覆盖中小行，它需要自筹资本，这个约束会在未来一两年内反复出现") + "。" + H(ORANGE, "说到底，银行股赚的是股息和估值修复的钱，不是一天1.5%的差价；用差价思维做银行，大概率会做反") + "。"
D["社区话题标签3"] = "银行分化"
